import React, { useState, useEffect } from "react";
import axios from "axios";
import "bootstrap/dist/css/bootstrap.min.css";
import live from "../../img/aulas-ao-vivo-coursifyme.jpg";

const LecionaAula = () => {
  const [aulas, setAulas] = useState([]);
  const [cursos, setCursos] = useState([]);
  const [filtro, setFiltro] = useState({
    cursoId: "",
    nivel: "",
  });

  // Carregar aulas e cursos ao montar o componente
  useEffect(() => {
    const carregarDados = async () => {
      try {
        const [resCursos, resAulas] = await Promise.all([
          axios.get("/api/cursos"),
          axios.get("/api/aulas"),
        ]);
        setCursos(resCursos.data);
        setAulas(resAulas.data);
      } catch (error) {
        console.error("Erro ao carregar dados:", error);
      }
    };
    carregarDados();
  }, []);

  // Filtrar aulas com base nos critérios selecionados
  const aulasFiltradas = aulas.filter((aula) => {
    const cursoMatch =
      !filtro.cursoId || aula.cursoId === parseInt(filtro.cursoId);
    const nivelMatch = !filtro.nivel || aula.curso?.nivel === filtro.nivel;
    return cursoMatch && nivelMatch;
  });

  // Função para adicionar nova aula
  const adicionarAula = async () => {
    try {
      const res = await axios.post("/api/aulas", {
        titulo: "Nova Aula",
        dataHoraInicio: new Date(),
        dataHoraFim: new Date(Date.now() + 3600000), // 1 hora depois
        professorId: 1, // Você precisará obter o ID do professor logado
        cursoId: filtro.cursoId,
      });
      setAulas([...aulas, res.data]);
    } catch (error) {
      console.error("Erro ao adicionar aula:", error);
    }
  };

  // Função para remover aula
  const removerAula = async (id) => {
    try {
      await axios.delete(`/api/aulas/${id}`);
      setAulas(aulas.filter((aula) => aula.id !== id));
    } catch (error) {
      console.error("Erro ao remover aula:", error);
    }
  };

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      {/* ... (seu código existente para navegação) ... */}

      <div className="d-flex justify-content-between w-75">
        <div>
          <h4>Aulas Ao Vivo</h4>
          <div className="card p-3">
            <img src={live} alt="Aula ao vivo" className="img-fluid" />
            <div className="d-flex justify-content-between mt-2">
              <button className="btn btn-primary">Entrar</button>
              <button className="btn btn-secondary">+ Nova Reunião</button>
            </div>
          </div>
        </div>
        <div>
          <div className="d-flex justify-content-between align-items-center mb-2">
            <h4>Aulas Gravadas</h4>
            <button className="btn btn-primary" onClick={adicionarAula}>
              Adicionar
            </button>
          </div>
          <div className="d-flex mb-2">
            <select
              className="form-select me-2"
              value={filtro.cursoId}
              onChange={(e) =>
                setFiltro({ ...filtro, cursoId: e.target.value })
              }
            >
              <option value="">Selecione o Curso</option>
              {cursos.map((curso) => (
                <option key={curso.id} value={curso.id}>
                  {curso.nome}
                </option>
              ))}
            </select>
            <select
              className="form-select"
              value={filtro.nivel}
              onChange={(e) => setFiltro({ ...filtro, nivel: e.target.value })}
            >
              <option value="">Selecione o Nível</option>
              <option value="Iniciante">Iniciante</option>
              <option value="Intermediário">Intermediário</option>
              <option value="Avançado">Avançado</option>
            </select>
          </div>
          <table className="table table-bordered bg-white">
            <tbody>
              {aulasFiltradas.map((aula) => (
                <tr key={aula.id}>
                  <td>
                    <a href="#">{aula.titulo}</a>
                    <div>
                      <small>
                        {new Date(aula.dataHoraInicio).toLocaleString()}
                      </small>
                    </div>
                  </td>
                  <td>
                    <button className="btn btn-link">✏️</button>
                    <button
                      className="btn btn-link"
                      onClick={() => removerAula(aula.id)}
                    >
                      🗑
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* ... (seu código existente para materiais de apoio) ... */}
    </div>
  );
};

export default LecionaAula;
